const copies={en,de,fr,es}
export function useUiCopy(){const {locale}=useLocale();return copies[locale]}
const unchangedLocaleKeys:Record<keyof typeof copies,CopyKey[]>={
  en:[],
  de:['sortName','community','tannin','storyline','chapterRegion','chapterAroma','chapterPause','region','sepAbbr'],
  fr:['latitude','vinification','chapterPause','minuteShort'],
  es:['chapterAroma','sepAbbr','minuteShort'],
}
export const uiCopyCompleteness=Object.fromEntries(Object.entries(copies).map(([locale,copy])=>[
  locale,
  Object.keys(en).filter(key=>!(key in copy)||(locale!=='en'&&copy[key as CopyKey]===en[key as CopyKey]&&!unchangedLocaleKeys[locale as keyof typeof copies].includes(key as CopyKey))),
])) as Record<keyof typeof copies,string[]>
